    if (angle_residual_rad != NULL) {
        *angle_residual_rad = INFINITY;
    }
    if (cross_residual_body != NULL) {
        cross_residual_body->x = 0.0;
        cross_residual_body->y = 0.0;
        cross_residual_body->z = 0.0;
    }

    // Validate input pointers
    if ((c_bi == NULL) || (check_body == NULL) || (check_inertial == NULL) ||
        (angle_residual_rad == NULL) || (cross_residual_body == NULL)) {
        return ADCS_E_NULL;
    }

    // Check finiteness of attitude matrix C_BI
    for (size_t i = 0; i < 3; ++i) {
        for (size_t j = 0; j < 3; ++j) {
            if (!isfinite(c_bi->m[i][j])) {
                return ADCS_E_NOT_FINITE;
            }
        }
    }

    // Check finiteness of input vectors
    if (!adcs_is_finite_vec3(check_body) || !adcs_is_finite_vec3(check_inertial)) {
        return ADCS_E_NOT_FINITE;
    }

    // Check for non-zero vectors
    double norm_body = adcs_vec3_norm(check_body);
    double norm_inertial = adcs_vec3_norm(check_inertial);

    if (norm_body <= ADCS_EPS_NORM) {
        return ADCS_E_RANGE;
    }
    if (norm_inertial <= ADCS_EPS_NORM) {
        return ADCS_E_RANGE;
    }

    // Normalize measured body vector b
    adcs_vec3_t b_normalized;
    if (adcs_vec3_normalize(check_body, ADCS_EPS_NORM, &b_normalized) != ADCS_OK) {
        return ADCS_E_RANGE;
    }

    // Map inertial vector to body frame: p = C_BI * check_inertial
    adcs_vec3_t p_mapped = adcs_mat3_mul_vec(c_bi, check_inertial);

    // Normalize predicted body vector p
    adcs_vec3_t p_normalized;
    if (adcs_vec3_normalize(&p_mapped, ADCS_EPS_NORM, &p_normalized) != ADCS_OK) {
        return ADCS_E_RANGE;
    }

    // Compute independent residuals
    // c = clamp(b dot p, -1, 1)
    double dot_val = adcs_vec3_dot(&b_normalized, &p_normalized);
    double c = ADCS_CLAMP(dot_val, -1.0, 1.0);

    // cross = b cross p
    adcs_vec3_t cross_vec = adcs_vec3_cross(&b_normalized, &p_normalized);
    double cross_norm = adcs_vec3_norm(&cross_vec);

    // angle = atan2(||cross||, c)
    double angle = atan2(cross_norm, c);

    // Output results
    *angle_residual_rad = angle;
    *cross_residual_body = cross_vec;

    return ADCS_OK;
}

